const sharp = require('sharp');
const fs = require('fs');
const path = require('path');

// Responsive sizes that MUST match the srcSet generated by
// src/components/ResponsiveImage.tsx (webpSizes) so the browser can
// actually resolve the variants it requests.
const RESPONSIVE_SIZES = {
  profile: [270, 320, 640],
  projects: [320, 640, 768, 1024, 1280]
};

// Quality per size bucket
const QUALITY_CONFIG = {
  webp: { small: 85, medium: 80, large: 75 }
};

// Base image extensions we accept as sources
const BASE_EXTENSIONS = ['.png', '.jpg', '.jpeg', '.webp'];

// All size values we ever generate (union of profile + projects), used to
// detect generated variants. We only treat a trailing "-<n>" as a size
// suffix when <n> is one of these known sizes, so base names that happen to
// contain numbers (e.g. "project-2048") are NOT mistaken for variants.
const ALL_SIZES = Array.from(
  new Set([...RESPONSIVE_SIZES.profile, ...RESPONSIVE_SIZES.projects])
);
const SIZE_SUFFIX_RE = new RegExp(
  `-(?:${ALL_SIZES.join('|')})(?=\\.[a-z0-9]+$)`,
  'i'
);

class ResponsiveImageGenerator {
  constructor() {
    this.publicDir = path.join(__dirname, '..', 'public');
    this.imagesDir = path.join(this.publicDir, 'images');
  }

  async generateResponsiveImages() {
    console.log('🖼️  Generando imágenes responsivas...');
    try {
      await this.processProfileImages();
      await this.processProjectImages();
      console.log('✅ Imágenes responsivas generadas exitosamente');
    } catch (error) {
      console.error('❌ Error generando imágenes responsivas:', error);
      process.exit(1);
    }
  }

  // Returns true if the filename looks like an already-generated size variant
  // (has a numeric size suffix right before the extension).
  isSizedVariant(fileName) {
    return SIZE_SUFFIX_RE.test(fileName);
  }

  // Returns the list of base (source) image names in a directory:
  // real images without any size suffix.
  getBaseImages(dir) {
    return fs.readdirSync(dir).filter(file => {
      const ext = path.extname(file).toLowerCase();
      if (!BASE_EXTENSIONS.includes(ext)) return false;
      return !this.isSizedVariant(file);
    });
  }

  async processProfileImages() {
    const profileDir = path.join(this.imagesDir, 'profile');
    if (!fs.existsSync(profileDir)) {
      console.log('⚠️  Directorio de perfil no encontrado, saltando...');
      return;
    }

    const profileWebP = path.join(profileDir, 'profile-david.webp');
    const profileJPG = path.join(profileDir, 'profile-david.jpg');
    const profileJPEG = path.join(profileDir, 'profile-david.jpeg');

    let profileImage = null;
    if (fs.existsSync(profileWebP)) profileImage = profileWebP;
    else if (fs.existsSync(profileJPG)) profileImage = profileJPG;
    else if (fs.existsSync(profileJPEG)) profileImage = profileJPEG;

    if (!profileImage) {
      console.log('⚠️  Imagen de perfil no encontrada, saltando...');
      return;
    }

    if (profileImage !== profileWebP) {
      console.log('♻️  Convirtiendo imagen de perfil a WebP base...');
      await this.generateImageVariant(profileImage, profileWebP, 1024, 'webp');
      profileImage = profileWebP;
    }

    console.log('📸 Procesando imagen de perfil...');
    for (const size of RESPONSIVE_SIZES.profile) {
      await this.generateImageVariant(
        profileImage,
        path.join(profileDir, `profile-david-${size}.webp`),
        size,
        'webp'
      );
    }
  }

  async processProjectImages() {
    const projectsDir = path.join(this.imagesDir, 'projects');
    if (!fs.existsSync(projectsDir)) {
      console.log('⚠️  Directorio de proyectos no encontrado, saltando...');
      return;
    }

    // Only process BASE images (no size suffix). This prevents the previous
    // bug where already-generated variants were reprocessed, chaining suffixes
    // like project-2048-1024-640-640-800.webp.
    const baseImages = this.getBaseImages(projectsDir);
    console.log(`📁 Procesando ${baseImages.length} imágenes base de proyectos...`);

    for (const file of baseImages) {
      const inputPath = path.join(projectsDir, file);
      const ext = path.extname(file);
      const baseName = path.basename(file, ext);

      // Ensure a base .webp exists for the <picture> webpSrc fallback.
      const baseWebp = path.join(projectsDir, `${baseName}.webp`);
      if (ext.toLowerCase() !== '.webp') {
        await this.generateImageVariant(inputPath, baseWebp, null, 'webp');
      }

      // Generate exactly the sizes the component requests.
      for (const size of RESPONSIVE_SIZES.projects) {
        const outputPath = path.join(projectsDir, `${baseName}-${size}.webp`);
        await this.generateImageVariant(inputPath, outputPath, size, 'webp');
      }
    }
  }

  async generateImageVariant(inputPath, outputPath, width, format) {
    try {
      if (fs.existsSync(outputPath)) {
        console.log(`⏭️  ${path.basename(outputPath)} ya existe, saltando...`);
        return;
      }

      let pipeline = sharp(inputPath);
      if (width) {
        pipeline = pipeline.resize(width, null, {
          withoutEnlargement: true,
          fit: 'inside'
        });
      }

      if (format === 'webp') {
        const quality = this.getQualityForSize(width || 1280, format);
        pipeline = pipeline.webp({ quality, effort: 6 });
      }

      await pipeline.toFile(outputPath);
      const sizeKB = Math.round(fs.statSync(outputPath).size / 1024);
      console.log(`✅ ${path.basename(outputPath)} - ${width || 'base'}px - ${sizeKB}KB`);
    } catch (error) {
      console.error(`❌ Error procesando ${inputPath}:`, error.message);
    }
  }

  getQualityForSize(width, format) {
    const config = QUALITY_CONFIG[format];
    if (width <= 320) return config.small;
    if (width <= 640) return config.medium;
    return config.large;
  }

  async generateSummary() {
    console.log('\n📊 Resumen de imágenes:');
    const dirs = ['profile', 'projects'];
    let totalFiles = 0;
    let totalSize = 0;

    for (const dir of dirs) {
      const dirPath = path.join(this.imagesDir, dir);
      if (!fs.existsSync(dirPath)) continue;

      const files = fs.readdirSync(dirPath)
        .filter(file => /\.(webp|jpg|jpeg|png)$/i.test(file));

      let dirSize = 0;
      files.forEach(file => {
        dirSize += fs.statSync(path.join(dirPath, file)).size;
      });

      totalFiles += files.length;
      totalSize += dirSize;
      console.log(`📁 ${dir}: ${files.length} archivos - ${Math.round(dirSize / 1024)}KB`);
    }

    console.log(`\n📈 Total: ${totalFiles} archivos - ${Math.round(totalSize / 1024)}KB`);
  }
}

if (require.main === module) {
  const generator = new ResponsiveImageGenerator();

  async function main() {
    await generator.generateResponsiveImages();
    await generator.generateSummary();
  }

  main().catch(console.error);
}

module.exports = ResponsiveImageGenerator;
